#!/usr/bin/env bash
set -e; R="$(cd "$(dirname "$0")/.."&&pwd)"; case "${NETWORK_API_IMPL:-python}" in python)exec python3 "$R/python/app.py";;node)exec node "$R/node/app.js";;typescript)npx --yes tsx "$R/typescript/app.ts";;go)go run "$R/go/main.go";;rust)cargo run --manifest-path "$R/rust/Cargo.toml";;java)mkdir -p "$R/java/out";javac "$R/java/Main.java" -d "$R/java/out";java -cp "$R/java/out" Main;;csharp)dotnet run --project "$R/csharp";;cpp)c++ -std=c++17 "$R/cpp/main.cpp" -o "$R/cpp/network-api";exec "$R/cpp/network-api";;dart)dart run "$R/dart/bin/main.dart";;kotlin)kotlinc "$R/kotlin/Main.kt" -include-runtime -d "$R/kotlin/network-api.jar";java -jar "$R/kotlin/network-api.jar";;swift)swift "$R/swift/main.swift";;php)php "$R/php/main.php";;ruby)ruby "$R/ruby/main.rb";;*)echo "Unknown NETWORK_API_IMPL";exit 2;;esac
